commands:
$target = (Resolve-Path 'cmds/ownsand-agent/internal/imagebuild/winiso_windows.go').Path
$expected = @{ 'first-entry' = @('default_index'); 'first-folded' = @('ambiguous_folded_name', 'exact_mixed-case_name') }
foreach ($variant in @('first-entry', 'first-folded')) {
    $replace = @{}
    $replace[$target] = Join-Path $scratch "$variant.go"
    $overlay = Join-Path $scratch "$variant-overlay.json"
    [IO.File]::WriteAllText($overlay, (ConvertTo-Json -InputObject @{ Replace = $replace } -Depth 4))
    $log = Join-Path $scratch "$variant.log"
    go test '-v' '-count=1' '-overlay' $overlay './cmds/ownsand-agent/internal/imagebuild' '-run' '^TestSelectEdition$' 2>&1 | Tee-Object -FilePath $log
    $testExit = $LASTEXITCODE
    $logText = Get-Content -LiteralPath $log -Raw
    $failed = @([regex]::Matches($logText, '(?m)^[ \t]+--- FAIL: TestSelectEdition/(\S+)') | ForEach-Object { $_.Groups[1].Value } | Sort-Object)
    if ($testExit -ne 1 -or ($failed -join ',') -ne ($expected[$variant] -join ',')) {
        throw "Unexpected test result for $variant. Exit $testExit. Failed subtests $($failed -join ',')."
    }
    Write-Output "Verified expected failures for $variant"
}
